use clap::{Arg, ArgAction, Command};

pub const TITLE: &str = "# msvc6t verbs";

pub const PREAMBLE: &str = "Generated by `msvc6t help --markdown` from the command-line definitions; \
                            `msvc6t help --markdown --out FILE` writes it again.";

fn flat(text: &str) -> String {
    text.split_whitespace().collect::<Vec<_>>().join(" ")
}

fn spec(a: &Arg) -> String {
    let value = a.get_value_names().map(|v| {
        v.iter()
            .map(|n| format!("<{n}>"))
            .collect::<Vec<_>>()
            .join(" ")
    });
    if a.is_positional() {
        let v = value.unwrap_or_else(|| format!("<{}>", a.get_id().as_str().to_uppercase()));
        let many = matches!(a.get_action(), ArgAction::Append);
        return format!("{v}{}", if many { "..." } else { "" });
    }
    let mut names = Vec::new();
    if let Some(c) = a.get_short() {
        names.push(format!("-{c}"));
    }
    if let Some(l) = a.get_long() {
        names.push(format!("--{l}"));
    }
    let mut s = names.join(", ");
    if a.get_action().takes_values() {
        s.push(' ');
        s.push_str(&value.unwrap_or_else(|| "<VALUE>".to_string()));
    }
    s
}

fn shown(a: &Arg) -> bool {
    let id = a.get_id().as_str();
    id != "help" && id != "version" && !a.is_hide_set()
}

fn section(out: &mut String, cmd: &mut Command, path: &str) {
    out.push_str(&format!("\n## `{path}`\n\n"));
    if let Some(about) = cmd.get_long_about().or(cmd.get_about()) {
        out.push_str(&flat(&about.to_string()));
        out.push_str("\n\n");
    }
    out.push_str("```text\n");
    out.push_str(cmd.render_usage().to_string().trim());
    out.push_str("\n```\n");
    let args: Vec<String> = cmd
        .get_arguments()
        .filter(|a| shown(a))
        .map(|a| {
            let help = a
                .get_long_help()
                .or(a.get_help())
                .map(|h| flat(&h.to_string()))
                .unwrap_or_default();
            format!("- `{}`: {help}\n", spec(a))
        })
        .collect();
    if !args.is_empty() {
        out.push('\n');
        out.push_str(&args.concat());
    }
    let subs: Vec<String> = cmd
        .get_subcommands()
        .map(|s| {
            let about = s
                .get_about()
                .map(|a| flat(&a.to_string()))
                .unwrap_or_default();
            format!("- `{}`: {about}\n", s.get_name())
        })
        .collect();
    if !subs.is_empty() {
        out.push_str("\nVerbs:\n\n");
        out.push_str(&subs.concat());
    }
    for sub in cmd.get_subcommands_mut().filter(|s| !s.is_hide_set()) {
        let p = format!("{path} {}", sub.get_name());
        section(out, sub, &p);
    }
}

#[must_use]
pub fn render(mut cmd: Command) -> String {
    cmd.build();
    let mut out = format!("{TITLE}\n\n{PREAMBLE}\n");
    let name = cmd.get_name().to_string();
    section(&mut out, &mut cmd, &name);
    out
}

#[cfg(test)]
mod tests {
    use super::*;
    use clap::CommandFactory as _;

    #[test]
    fn every_verb_gets_a_section_with_its_usage_and_options() {
        let md = render(crate::cli::Cli::command());
        assert!(md.starts_with(TITLE));
        for h in ["## `msvc6t`", "## `msvc6t lint`", "## `msvc6t help`"] {
            assert!(md.contains(h), "{h}");
        }
        assert!(md.contains("Usage: msvc6t lint [OPTIONS]"), "{md}");
        assert!(md.contains("- `--root <DIR>`: "), "{md}");
        assert!(md.contains("- `<VERB>...`: "), "{md}");
        assert!(!md.contains("--help"), "the built-in flags are left out");
    }
}
